const ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const judge = (item, v) => {
  if (typeof item.answer === "number") return leadNumber(v) === item.answer;
  return String(v).trim().toLowerCase() === String(item.answer).trim().toLowerCase();
};
const oracle = () => {
  const countOn = (from, step, times) => {
    let x = from;
    for (let k = 0; k < times; k++) x = x + step;
    return x;
  };
  const at = (L) => ALPHA.indexOf(L) + 1;
  const rows = [
    [1, 0, countOn(22, 12 - 7, 1)],
    [1, 1, countOn(23, 11 - 5, 1)],
    [1, 2, countOn(56, 48 - 56, 7)],
    [2, 0, countOn(at("H"), at("D") - at("B"), 1)],
    [2, 1, ALPHA.charAt(at("J") - 1 + (at("D") - at("A")))],
    [2, 2, countOn(at("S"), at("V") - at("Y"), 1)],
    [3, 0, 11 - 2 * Math.floor(11 / 2) === 0 ? "even" : "odd"],
    [3, 1, 14 - 2 * Math.floor(14 / 2) === 0 ? "even" : "odd"],
    [3, 2, countOn(37, 33 - 31, 1)],
    [4, 0, countOn(48, 48, 1)],
    [4, 1, countOn(72, 72, 1)],
    [4, 2, countOn(4, 7, 1)]
  ];
  return rows.every((r) => String(PHASES[r[0] - 1].items[r[1]].answer) === String(r[2]));
};
