const answer = (item, v) => item.pad === "enter" && HOOK.set ? HOOK.set(v) : void 0;
const check = () => HOOK.check ? HOOK.check() : void 0;
const laneOf = (i, len, down) => down ? len - 1 - i : i;
const trackX0 = (len) => Math.round((1086 - (len * 96 + (len - 1) * 12)) / 2);
const stoneCx = (i, len, down) => trackX0(len) + laneOf(i, len, down) * 108 + 48;
const barScale = (series) => {
  const steps = series.slice(1).map((v, i) => Math.abs(v - series[i]));
  const head = steps.length > 1 ? steps.slice(0, -1) : steps;
  return 100 / Math.max(1, Math.max.apply(null, head));
};
const arcPath = (x1, x2, top, ctrl) => `M ${x1} ${top} C ${x1} ${ctrl}, ${x2} ${ctrl}, ${x2} ${top}`;
const signed = (d) => d < 0 ? "−" + Math.abs(d) : "+" + d;
const heapSpot = (k, total, M) => {
  const a = k * 2.399963 % (Math.PI * 2);
  const r = 18 + 64 * Math.sqrt((k + 1) / (total + 1));
  return { x: M.tray.cx + r * Math.cos(a) * 1.75, y: M.tray.cy + r * Math.sin(a) };
};
const pairSpot = (k, heap, M) => {
  const alone = heap % 2 === 1 && k === heap - 1;
  const col = Math.floor(k / 2);
  return { x: M.tray.x + 64 + col * M.tray.col + (alone ? 44 : 0), y: alone ? M.tray.cy : k % 2 === 0 ? M.tray.top : M.tray.bot, alone };
};
const freeSeries = (s, rule, len) => {
  const out = [s];
  if (rule === "step") {
    for (let k = 1; k < len; k++) out.push(out[k - 1] + 2);
  } else if (rule === "away") {
    for (let k = 1; k < len; k++) {
      const v = out[k - 1] - 2;
      if (v < 0) break;
      out.push(v);
    }
  } else if (rule === "self") {
    for (let k = 1; k < len; k++) out.push(out[k - 1] + out[k - 1]);
  } else if (rule === "two") {
    out.push(s + 2);
    for (let k = 2; k < len; k++) out.push(out[k - 1] + out[k - 2]);
  }
  return out;
};
